func (e Environment) IsStaging() bool { return e == EnvStaging }

// IsDevelopment reporta si Krypton corre en desarrollo local.
func (e Environment) IsDevelopment() bool { return e == EnvDevelopment }

// Valid indica si el entorno es reconocido.
func (e Environment) Valid() bool {
	switch e {
	case EnvDevelopment, EnvStaging, EnvProduction:
		return true
	default:
		return false
	}
}

// String implementa fmt.Stringer.
