type AntiraidConfig struct {
	Enabled          bool          `env:"ANTIRAID_ENABLED" envDefault:"true"`
	DefaultAction    string        `env:"ANTIRAID_DEFAULT_ACTION" envDefault:"timeout"`
	WindowDuration   time.Duration `env:"ANTIRAID_WINDOW_DURATION" envDefault:"10s"`
	ScoreThreshold   int           `env:"ANTIRAID_SCORE_THRESHOLD" envDefault:"70"`
	JoinFloodLimit   int           `env:"ANTIRAID_JOIN_FLOOD_LIMIT" envDefault:"10"`
	MessageSpamLimit int           `env:"ANTIRAID_MESSAGE_SPAM_LIMIT" envDefault:"8"`
	MentionSpamLimit int           `env:"ANTIRAID_MENTION_SPAM_LIMIT" envDefault:"6"`
	LinkSpamLimit    int           `env:"ANTIRAID_LINK_SPAM_LIMIT" envDefault:"4"`
	MinAccountAge    time.Duration `env:"ANTIRAID_MIN_ACCOUNT_AGE" envDefault:"168h"`
	LockdownCooldown time.Duration `env:"ANTIRAID_LOCKDOWN_COOLDOWN" envDefault:"5m"`
	AutoMitigate     bool          `env:"ANTIRAID_AUTO_MITIGATE" envDefault:"true"`
}

