// Logging
// -------------------------------------------------------------

// LogConfig controla el logger estructurado (log/slog).
type LogConfig struct {
	Level  string `env:"LOG_LEVEL" envDefault:"info"`
	Format string `env:"LOG_FORMAT" envDefault:"console"`
	Source bool   `env:"LOG_SOURCE" envDefault:"false"`
}

// -------------------------------------------------------------
// Health server
// -------------------------------------------------------------

// HealthConfig define el servidor HTTP de probes para K8s/Docker.
type HealthConfig struct {
	Addr         string        `env:"HEALTH_ADDR" envDefault:":8080"`
	ReadTimeout  time.Duration `env:"HEALTH_READ_TIMEOUT" envDefault:"5s"`
	WriteTimeout time.Duration `env:"HEALTH_WRITE_TIMEOUT" envDefault:"10s"`
}

